{"command":"printf 'uci\nsetoption name Threads value 1\nsetoption name Hash value 16\nsetoption name MultiPV value 5\nisready\nposition fen rnbqkbnr/pp2pppp/2c5/3pP3/3P4/8/PPP2PPP/RNBQKBNR b KQkq - 0 3\n' >/dev/null
printf 'uci\nsetoption name Threads value 1\nsetoption name Hash value 16\nsetoption name MultiPV value 6\nisready\nposition fen rnbqkbnr/pp2pppp/2p5/3pP3/3P4/8/PPP2PPP/RNBQKBNR b KQkq - 0 3\ngo depth 18\n' | /usr/local/bin/stockfish 2>&1 | grep -E "depth 1[5-8]|bestmove" | awk '{
  # print depth, score, pv truncated
  line=$0
  print line
}' | head -80"}

{"command":"printf 'uci\nsetoption name Threads value 1\nsetoption name Hash value 16\nsetoption name MultiPV value 4\nisready\nposition fen rnbqkbnr/pp2pppp/2p5/3pP3/3P4/8/PPP2PPP/RNBQKBNR b KQkq - 0 3\ngo depth 16\n' | /usr/local/bin/stockfish 2>&1 | grep "^info depth" | awk '
{
  depth=""; score=""; multipv=1; pv=""
  for(i=1;i<=NF;i++){
    if($i=="depth") depth=$(i+1)
    if($i=="multipv") multipv=$(i+1)
    if($i=="score"){ if($(i+1)=="cp") score=$(i+2); else score=$(i+1)" "$(i+2) }
    if($i=="pv"){ pv=""; for(j=i+1;j<=NF && j<i+10;j++) pv=pv" "$j }
  }
  printf "d=%s mpv=%s score=%s pv=%s\n", depth, multipv, score, pv
}'"}
